// Normalize direct WF03/WF98 invocation and protected webhook input
// into one plain payload object.

const input = $json ?? {};

const payload =
  input.body !== null &&
  typeof input.body === 'object' &&
  !Array.isArray(input.body)
    ? input.body
    : input;

return {
  json: payload,
};

// Validate and normalize the authoritative WF04 invocation contract.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (typeof value !== 'string') {
    throw new Error(`${fieldName} must be a UUID string`);
  }

  const normalized = value.trim().toLowerCase();

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(`${fieldName} must be a valid UUID`);
  }

  return normalized;
}

function optionalUuid(value, fieldName) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  return requireUuid(value, fieldName);
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === '' ? null : normalized;
}

const triggerSource = String(
  input.trigger_source ?? '',
)
  .trim()
  .toLowerCase();

if (
  triggerSource !== 'wf03' &&
  triggerSource !== 'wf98'
) {
  throw new Error(
    'trigger_source must be wf03 or wf98',
  );
}

const caseId = requireUuid(
  input.case_id,
  'case_id',
);

const correlationId = requireUuid(
  input.correlation_id,
  'correlation_id',
);

const acceptedSubmissionId = optionalUuid(
  input.accepted_submission_id,
  'accepted_submission_id',
);

const clientId = optionalUuid(
  input.client_id,
  'client_id',
);

const externalOperationId = optionalUuid(
  input.external_operation_id,
  'external_operation_id',
);

const recoveryReason = optionalText(
  input.recovery_reason,
);

if (triggerSource === 'wf03') {
  if (
    acceptedSubmissionId === null ||
    clientId === null
  ) {
    throw new Error(
      'WF03 invocation requires accepted_submission_id and client_id',
    );
  }

  if (
    externalOperationId !== null ||
    recoveryReason !== null
  ) {
    throw new Error(
      'WF03 invocation must not contain recovery fields',
    );
  }
}

if (triggerSource === 'wf98') {
  if (
    acceptedSubmissionId !== null ||
    clientId !== null
  ) {
    throw new Error(
      'WF98 invocation must not contain WF03 identity fields',
    );
  }

  if (
    externalOperationId === null &&
    recoveryReason !== 'missing_initial_dispatch'
  ) {
    throw new Error(
      'WF98 invocation requires external_operation_id or missing_initial_dispatch recovery',
    );
  }

  if (
    externalOperationId !== null &&
    recoveryReason !== null
  ) {
    throw new Error(
      'WF98 operation retry and state-gap recovery are mutually exclusive',
    );
  }
}

return {
  json: {
    case_id: caseId,
    correlation_id: correlationId,
    trigger_source: triggerSource,
    accepted_submission_id: acceptedSubmissionId,
    client_id: clientId,
    external_operation_id: externalOperationId,
    recovery_reason: recoveryReason,
  },
};

// Validate WF04 runtime configuration and build a deterministic
// approval request context shared by initial dispatch and retries.

const crypto = require('crypto');
const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(`${fieldName} must not be blank`);
  }

  return normalized;
}

function readInteger(name, minimum, maximum) {
  const rawValue = requireText(
    $env[name],
    name,
  );

  const value = Number(rawValue);

  if (
    !Number.isInteger(value) ||
    value < minimum ||
    value > maximum
  ) {
    throw new Error(
      `${name} must be an integer between ${minimum} and ${maximum}`,
    );
  }

  return value;
}

const recipientEmail = requireText(
  $env.APPROVAL_RECIPIENT_EMAIL,
  'APPROVAL_RECIPIENT_EMAIL',
).toLowerCase();

if (
  !/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(
    recipientEmail,
  )
) {
  throw new Error(
    'APPROVAL_RECIPIENT_EMAIL is invalid',
  );
}

const templateKey = requireText(
  $env.APPROVAL_TEMPLATE_KEY,
  'APPROVAL_TEMPLATE_KEY',
);

if (templateKey !== 'manual_approval_v1') {
  throw new Error(
    'APPROVAL_TEMPLATE_KEY must equal manual_approval_v1',
  );
}

const responseTimeoutHours = readInteger(
  'APPROVAL_RESPONSE_TIMEOUT_HOURS',
  1,
  720,
);

const leaseSeconds = readInteger(
  'WF04_OPERATION_LEASE_SECONDS',
  1,
  2592000,
);

if (
  leaseSeconds <=
  responseTimeoutHours * 3600
) {
  throw new Error(
    'WF04_OPERATION_LEASE_SECONDS must exceed the approval response timeout',
  );
}

const maxAttempts = readInteger(
  'WF04_OPERATION_MAX_ATTEMPTS',
  1,
  20,
);

const waitingExecutionId = requireText(
  $execution.id,
  'execution_id',
);

const messageMarker =
  'b2b-approval-' +
  crypto
    .createHash('sha256')
    .update(input.case_id)
    .digest('hex')
    .slice(0, 24);

return {
  json: {
    ...input,

    waiting_execution_id:
      waitingExecutionId,

    recipient_email:
      recipientEmail,

    template_key:
      templateKey,

    message_marker:
      messageMarker,

    response_timeout_hours:
      responseTimeoutHours,

    lease_seconds:
      leaseSeconds,

    max_attempts:
      maxAttempts,

    sender_name:
      requireText(
        $env.APPROVAL_REQUEST_SENDER_NAME,
        'APPROVAL_REQUEST_SENDER_NAME',
      ),

    support_contact:
      String(
        $env.APPROVAL_SUPPORT_CONTACT ?? '',
      ).trim() || null,
  },
};

// Normalize the authoritative PostgreSQL preparation result
// before routing WF04 to sending, no-op, or intervention.

const row = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(`${fieldName} must not be blank`);
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === '' ? null : normalized;
}

function optionalUuid(value, fieldName) {
  const normalized = optionalText(value);

  if (normalized === null) {
    return null;
  }

  if (!UUID_PATTERN.test(normalized)) {
    throw new Error(`${fieldName} must be a valid UUID`);
  }

  return normalized.toLowerCase();
}

const inputContext =
  isPlainObject(row.input_context)
    ? row.input_context
    : {};

const preparationOutcome = requireText(
  row.preparation_outcome,
  'preparation_outcome',
);

const operationClaimOutcome = optionalText(
  row.operation_claim_outcome,
);

const operationId = optionalUuid(
  row.operation_id,
  'operation_id',
);

const caseId =
  optionalUuid(
    row.case_id,
    'case_id',
  ) ??
  optionalUuid(
    inputContext.case_id,
    'input_context.case_id',
  );

const correlationId =
  optionalUuid(
    row.correlation_id,
    'correlation_id',
  ) ??
  optionalUuid(
    inputContext.correlation_id,
    'input_context.correlation_id',
  );

let preparationDecision;

if (preparationOutcome === 'ready_to_send') {
  if (
    operationClaimOutcome !== 'claimed' ||
    operationId === null ||
    row.operation_status !== 'in_progress' ||
    row.approval_step_status !== 'waiting'
  ) {
    throw new Error(
      'ready_to_send returned an inconsistent operation state',
    );
  }

  preparationDecision = 'send_approval_request';

} else if (
  preparationOutcome === 'active_wait_exists'
) {
  if (
    operationClaimOutcome !== 'busy' ||
    operationId === null ||
    row.operation_status !== 'in_progress' ||
    row.approval_step_status !== 'waiting'
  ) {
    throw new Error(
      'active_wait_exists returned an inconsistent operation state',
    );
  }

  preparationDecision = 'no_action';

} else if (
  [
    'already_approved',
    'already_rejected',
    'not_required',
    'not_due',
  ].includes(preparationOutcome)
) {
  preparationDecision = 'no_action';

} else {
  preparationDecision =
    'operator_intervention_required';
}

const waitingExecutionId = optionalText(
  row.waiting_execution_id ??
  inputContext.waiting_execution_id,
);

return {
  json: {
    workflow: 'WF04',

    preparation_decision:
      preparationDecision,

    preparation_outcome:
      preparationOutcome,

    operation_claim_outcome:
      operationClaimOutcome,

    operation_id:
      operationId,

    operation_status:
      optionalText(row.operation_status),

    operation_attempt_count:
      row.operation_attempt_count ?? null,

    operation_max_attempts:
      row.operation_max_attempts ?? null,

    operation_lease_expires_at:
      row.operation_lease_expires_at ?? null,

    case_id:
      caseId,

    correlation_id:
      correlationId,

    case_state:
      optionalText(row.case_state),

    accepted_submission_id:
      optionalUuid(
        row.accepted_submission_id,
        'accepted_submission_id',
      ),

    client_id:
      optionalUuid(
        row.client_id,
        'client_id',
      ),

    approval_step_id:
      optionalUuid(
        row.approval_step_id,
        'approval_step_id',
      ),

    approval_step_status:
      optionalText(row.approval_step_status),

    waiting_execution_id:
      waitingExecutionId,

    lease_owner:
      waitingExecutionId === null
        ? null
        : `WF04:${waitingExecutionId}`,

    recipient_email:
      optionalText(row.recipient_email),

    response_timeout_hours:
      row.response_timeout_hours ?? null,

    template_key:
      optionalText(row.template_key),

    message_marker:
      optionalText(row.message_marker),

    legal_name:
      optionalText(row.legal_name),

    company_identifier_country:
      optionalText(
        row.company_identifier_country,
      ),

    company_identifier_type:
      optionalText(
        row.company_identifier_type,
      ),

    company_identifier_value:
      optionalText(
        row.company_identifier_value,
      ),

    primary_contact_first_name:
      optionalText(
        row.primary_contact_first_name,
      ),

    primary_contact_last_name:
      optionalText(
        row.primary_contact_last_name,
      ),

    primary_contact_email:
      optionalText(
        row.primary_contact_email,
      ),

    primary_contact_phone:
      optionalText(
        row.primary_contact_phone,
      ),

    case_created_at:
      row.case_created_at ?? null,

    trigger_source:
      optionalText(inputContext.trigger_source),

    sender_name:
      optionalText(inputContext.sender_name),

    support_contact:
      optionalText(inputContext.support_contact),
  },
};

// Return a clean idempotent result when WF04 must not send
// another approval request.

const input = $json ?? {};

if (input.preparation_decision !== 'no_action') {
  throw new Error(
    'Return No Action Result received an invalid preparation decision',
  );
}

return {
  json: {
    workflow: 'WF04',

    result: 'no_action',

    preparation_outcome:
      input.preparation_outcome ?? null,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    operation_id:
      input.operation_id ?? null,

    case_state:
      input.case_state ?? null,

    approval_step_status:
      input.approval_step_status ?? null,
  },
};

// Build a plain-text approval email only from
// authoritative PostgreSQL data.

const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function displayValue(value) {
  const normalized =
    String(value ?? '').trim();

  return normalized === ''
    ? 'Not provided'
    : normalized;
}

if (
  input.preparation_decision !==
  'send_approval_request'
) {
  throw new Error(
    'Build Approval Email received an invalid preparation decision',
  );
}

const caseId = requireText(
  input.case_id,
  'case_id',
);

const operationId = requireText(
  input.operation_id,
  'operation_id',
);

const recipientEmail = requireText(
  input.recipient_email,
  'recipient_email',
);

const legalName = requireText(
  input.legal_name,
  'legal_name',
);

const identifier = [
  input.company_identifier_country,
  input.company_identifier_type,
  input.company_identifier_value,
]
  .filter(
    (value) =>
      value !== null &&
      value !== undefined &&
      String(value).trim() !== '',
  )
  .join(' / ');

const contactName = [
  input.primary_contact_first_name,
  input.primary_contact_last_name,
]
  .filter(
    (value) =>
      value !== null &&
      value !== undefined &&
      String(value).trim() !== '',
  )
  .join(' ');

const approvalSubject =
  `Approval required: ${legalName}`;

const messageLines = [
  'Manual onboarding approval required',
  '',
  'Review the validated client information below.',
  'Select Approve or Reject using the buttons in this email.',
  '',
  `Company: ${legalName}`,
  `Company identifier: ${displayValue(identifier)}`,
  `Primary contact: ${displayValue(contactName)}`,
  `Contact email: ${displayValue(input.primary_contact_email)}`,
  `Contact phone: ${displayValue(input.primary_contact_phone)}`,
  '',
  `Case ID: ${caseId}`,
  `Operation ID: ${operationId}`,
  `Message marker: ${displayValue(input.message_marker)}`,
];

if (input.support_contact) {
  messageLines.push(
    '',
    `Support: ${input.support_contact}`,
  );
}

return {
  json: {
    ...input,

    approval_recipient:
      recipientEmail,

    approval_subject:
      approvalSubject,

    approval_message:
      messageLines.join('\n'),
  },
};

// Classify the direct Gmail send-and-wait result.
// Authoritative case and operation context is restored later
// from PostgreSQL by the current n8n execution ID.

const input = $json ?? {};

function optionalText(
  value,
  maximumLength = 1000,
) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value)
    .replace(
      /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
      ' ',
    )
    .replace(/\s+/g, ' ')
    .trim();

  return normalized === ''
    ? null
    : normalized.slice(
        0,
        maximumLength,
      );
}

function extractErrorMessage(value) {
  if (typeof value === 'string') {
    return optionalText(value);
  }

  if (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return optionalText(
      value.message ??
      value.description ??
      value.error ??
      JSON.stringify(value),
    );
  }

  return null;
}

const waitingExecutionId =
  optionalText(
    $execution.id,
    200,
  );

if (waitingExecutionId === null) {
  throw new Error(
    'Current n8n execution ID is unavailable',
  );
}

const approved =
  typeof input?.data?.approved ===
    'boolean'
    ? input.data.approved
    : typeof input.approved ===
        'boolean'
      ? input.approved
      : typeof input?.response?.approved ===
          'boolean'
        ? input.response.approved
        : null;

const providerError =
  extractErrorMessage(
    input.error,
  ) ??
  (
    input.name === 'NodeApiError' ||
    input.name === 'NodeOperationError'
      ? extractErrorMessage(input)
      : null
  );

const commonResult = {
  workflow:
    'WF04',

  waiting_execution_id:
    waitingExecutionId,

  lease_owner:
    `WF04:${waitingExecutionId}`,
};

if (approved !== null) {
  const respondedAt =
    optionalText(
      input?.data?.respondedAt ??
      input?.data?.responded_at ??
      input?.respondedAt ??
      input?.responded_at,
      100,
    ) ??
    new Date().toISOString();

  return {
    json: {
      ...commonResult,

      approval_wait_outcome:
        'response_received',

      decision:
        approved
          ? 'approved'
          : 'rejected',

      responded_at:
        respondedAt,

      gmail_message_id:
        optionalText(
          input?.data?.messageId ??
          input?.data?.message_id ??
          input?.messageId ??
          input?.message_id,
          500,
        ),

      gmail_thread_id:
        optionalText(
          input?.data?.threadId ??
          input?.data?.thread_id ??
          input?.threadId ??
          input?.thread_id,
          500,
        ),

      operator_comment:
        optionalText(
          input?.data?.comment ??
          input?.data?.text ??
          input?.comment,
          2000,
        ),

      response_source:
        'n8n_send_and_wait',
    },
  };
}

if (providerError !== null) {
  return {
    json: {
      ...commonResult,

      approval_wait_outcome:
        'gmail_send_failed',

      error_class:
        'gmail_send_failure',

      error_message:
        providerError,

      error_details: {
        provider:
          'gmail',

        stage:
          'send_approval_request',
      },
    },
  };
}

// When the configured wait deadline expires,
// n8n resumes the node without an approval response.
// The original node input can be returned in this case.

if (
  input.preparation_decision ===
    'send_approval_request'
) {
  return {
    json: {
      ...commonResult,

      approval_wait_outcome:
        'approval_response_timeout',

      error_class:
        'approval_response_timeout',

      error_message:
        'No approval response was received before the configured deadline.',

      error_details: {
        provider:
          'gmail',

        stage:
          'wait_for_approval',

        timeout_hours:
          Number(
            input.response_timeout_hours,
          ) || null,
      },
    },
  };
}

return {
  json: {
    ...commonResult,

    approval_wait_outcome:
      'invalid_wait_result',

    error_class:
      'workflow_contract_failure',

    error_message:
      'WF04 received an unsupported Gmail send-and-wait result.',

    error_details: {
      provider:
        'gmail',

      stage:
        'send_and_wait_result_classification',

      received_fields:
        Object.keys(input)
          .slice(0, 50),
    },
  },
};

// Validate the authoritative WF04 finalization result
// and determine the next workflow action.

const input = $json ?? {};

const result =
  input.finalization_result;

if (
  result === null ||
  typeof result !== 'object' ||
  Array.isArray(result)
) {
  throw new Error(
    'finalization_result must be a JSON object',
  );
}

const lookupOutcome =
  String(
    result.context_lookup_outcome ?? '',
  ).trim();

const finalizationOutcome =
  String(
    result.finalization_outcome ?? '',
  ).trim();

const decision =
  String(
    result.decision ??
    result.final_decision ??
    '',
  ).trim();

let nextAction;

if (
  lookupOutcome === 'context_resolved' &&
  finalizationOutcome === 'finalized'
) {
  if (
    result.final_step_status !== 'completed' ||
    result.final_operation_status !== 'succeeded'
  ) {
    throw new Error(
      'Finalized WF04 response returned inconsistent terminal state',
    );
  }

  if (
    decision === 'approved' &&
    result.final_case_state === 'approved'
  ) {
    nextAction =
      'dispatch_wf05';

  } else if (
    decision === 'rejected' &&
    result.final_case_state === 'rejected'
  ) {
    nextAction =
      'complete_rejected';

  } else {
    throw new Error(
      'WF04 decision does not match the finalized case state',
    );
  }

} else if (
  lookupOutcome === 'context_resolved' &&
  finalizationOutcome === 'already_finalized'
) {
  nextAction =
    'no_action';

} else {
  nextAction =
    'operator_intervention_required';
}

return {
  json: {
    workflow:
      'WF04',

    next_action:
      nextAction,

    context_lookup_outcome:
      lookupOutcome || null,

    finalization_outcome:
      finalizationOutcome || null,

    case_id:
      result.case_id ?? null,

    operation_id:
      result.operation_id ?? null,

    waiting_execution_id:
      result.waiting_execution_id ?? null,

    decision:
      decision || null,

    final_case_state:
      result.final_case_state ?? null,

    final_step_status:
      result.final_step_status ?? null,

    final_operation_status:
      result.final_operation_status ?? null,

    final_client_id:
      result.final_client_id ?? null,

    final_accepted_submission_id:
      result.final_accepted_submission_id ?? null,
  },
};

// Return the terminal WF04 result after a valid rejection.

const input = $json ?? {};

if (input.next_action !== 'complete_rejected') {
  throw new Error(
    'Return Rejected Result received an invalid next action',
  );
}

if (
  input.decision !== 'rejected' ||
  input.final_case_state !== 'rejected' ||
  input.final_step_status !== 'completed' ||
  input.final_operation_status !== 'succeeded'
) {
  throw new Error(
    'Rejected WF04 result contains an inconsistent terminal state',
  );
}

return {
  json: {
    workflow: 'WF04',
    result: 'rejected',

    case_id:
      input.case_id ?? null,

    operation_id:
      input.operation_id ?? null,

    decision:
      input.decision,

    case_state:
      input.final_case_state,

    approval_step_status:
      input.final_step_status,

    operation_status:
      input.final_operation_status,
  },
};

// Return an idempotent result when this approval response
// was already finalized previously.

const input = $json ?? {};

if (input.next_action !== 'no_action') {
  throw new Error(
    'Return Finalization No Action Result received an invalid next action',
  );
}

return {
  json: {
    workflow: 'WF04',
    result: 'no_action',

    finalization_outcome:
      input.finalization_outcome ?? null,

    case_id:
      input.case_id ?? null,

    operation_id:
      input.operation_id ?? null,

    decision:
      input.decision ?? null,

    case_state:
      input.final_case_state ?? null,
  },
};

// Normalize a Gmail wait failure before PostgreSQL
// restores the authoritative case and operation context.

const input = $json ?? {};

function requireText(
  value,
  fieldName,
  maximumLength = 1000,
) {
  const normalized =
    String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  if (
    normalized.length >
    maximumLength
  ) {
    throw new Error(
      `${fieldName} exceeds ${maximumLength} characters`,
    );
  }

  return normalized;
}

const outcome =
  requireText(
    input.approval_wait_outcome ??
      'invalid_wait_result',
    'approval_wait_outcome',
    100,
  );

const allowedOutcomes =
  new Set([
    'approval_response_timeout',
    'gmail_send_failed',
    'invalid_wait_result',
  ]);

if (!allowedOutcomes.has(outcome)) {
  throw new Error(
    'Approval response must not enter failure finalization',
  );
}

const waitingExecutionId =
  requireText(
    input.waiting_execution_id,
    'waiting_execution_id',
    200,
  );

let errorClass;

if (
  outcome ===
  'approval_response_timeout'
) {
  errorClass =
    'approval_response_timeout';

} else if (
  outcome ===
  'gmail_send_failed'
) {
  errorClass =
    'gmail_send_failure';

} else {
  errorClass =
    'workflow_contract_failure';
}

const errorMessage =
  requireText(
    input.error_message ??
      'WF04 approval wait failed',
    'error_message',
    1000,
  );

return {
  json: {
    waiting_execution_id:
      waitingExecutionId,

    approval_wait_outcome:
      outcome,

    error_class:
      errorClass,

    error_message:
      errorMessage,

    error_summary: {
      approval_wait_outcome:
        outcome,

      error_message:
        errorMessage,

      provider:
        input.error_details?.provider ??
        null,

      stage:
        input.error_details?.stage ??
        null,

      timeout_hours:
        input.error_details?.timeout_hours ??
        null,

      received_fields:
        input.error_details?.received_fields ??
        null,
    },
  },
};

// Normalize the authoritative PostgreSQL result produced
// after an approval wait or Gmail delivery failure.

const row = $json ?? {};

function parseObject(value) {
  if (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);

      if (
        parsed !== null &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }
    } catch {
      return {};
    }
  }

  return {};
}

function optionalText(value, maximumLength = 1000) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value).trim();

  return normalized === ''
    ? null
    : normalized.slice(0, maximumLength);
}

const context =
  parseObject(
    row.input_context,
  );

const finalizationOutcome =
  optionalText(
    row.finalization_outcome,
    100,
  );

const finalOperationStatus =
  optionalText(
    row.final_operation_status,
    100,
  );

const finalStepStatus =
  optionalText(
    row.final_step_status,
    100,
  );

const finalCaseState =
  optionalText(
    row.final_case_state,
    100,
  );

let nextAction =
  'operator_intervention_required';

if (
  finalizationOutcome === 'finalized' &&
  finalOperationStatus === 'failed_retryable' &&
  finalStepStatus === 'failed_retryable' &&
  finalCaseState === 'awaiting_approval'
) {
  nextAction =
    'return_failed_retryable';

} else if (
  finalizationOutcome === 'finalized' &&
  finalOperationStatus === 'failed_terminal' &&
  finalStepStatus === 'failed_terminal' &&
  finalCaseState === 'awaiting_approval'
) {
  nextAction =
    'notify_terminal_failure';

} else if (
  finalizationOutcome === 'lease_not_owned'
) {
  nextAction =
    'no_action';

} else if (
  finalizationOutcome ===
    'failure_context_invalid' &&
  (
    [
      'failed_retryable',
      'failed_terminal',
      'succeeded',
    ].includes(finalOperationStatus) ||
    [
      'failed_retryable',
      'failed_terminal',
      'completed',
    ].includes(finalStepStatus) ||
    [
      'approved',
      'rejected',
    ].includes(finalCaseState)
  )
) {
  nextAction =
    'no_action';
}

return {
  json: {
    ...context,

    next_action:
      nextAction,

    failure_finalization_outcome:
      finalizationOutcome,

    final_operation_status:
      finalOperationStatus,

    final_step_status:
      finalStepStatus,

    final_case_state:
      finalCaseState,
  },
};

// Return either a scheduled retry result or a clean
// no-action result for an obsolete failure execution.

const input = $json ?? {};

if (
  input.next_action ===
  'return_failed_retryable'
) {
  if (
    input.final_operation_status !==
      'failed_retryable' ||
    input.final_step_status !==
      'failed_retryable' ||
    input.final_case_state !==
      'awaiting_approval'
  ) {
    throw new Error(
      'Retryable WF04 failure contains inconsistent persisted states',
    );
  }

  return {
    json: {
      workflow:
        'WF04',

      result:
        'failed_retryable',

      case_id:
        input.case_id ?? null,

      correlation_id:
        input.correlation_id ?? null,

      external_operation_id:
        input.operation_id ?? null,

      operation_status:
        input.final_operation_status,

      approval_step_status:
        input.final_step_status,

      next_retry_at:
        input.next_retry_at ?? null,
    },
  };
}

if (input.next_action === 'no_action') {
  return {
    json: {
      workflow:
        'WF04',

      result:
        'no_action',

      case_id:
        input.case_id ?? null,

      external_operation_id:
        input.operation_id ?? null,

      failure_finalization_outcome:
        input.failure_finalization_outcome ??
        null,

      operation_status:
        input.final_operation_status ??
        null,

      approval_step_status:
        input.final_step_status ??
        null,

      case_state:
        input.final_case_state ??
        null,
    },
  };
}

throw new Error(
  'Return Approval Failure Result received an invalid next action',
);

// Build the canonical WF99 explicit-internal envelope
// for terminal or inconsistent WF04 approval failures.

const input = $json ?? {};

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function optionalUuid(value) {
  if (typeof value !== 'string') {
    return null;
  }

  const normalized =
    value.trim().toLowerCase();

  return UUID_PATTERN.test(normalized)
    ? normalized
    : null;
}

function safeText(value, maximumLength = 1000) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized =
    String(value)
      .replace(
        /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,
        ' ',
      )
      .replace(/\s+/g, ' ')
      .trim();

  return normalized === ''
    ? null
    : normalized.slice(0, maximumLength);
}

const terminalFailure =
  input.next_action ===
  'notify_terminal_failure';

const originalErrorClass =
  safeText(
    input.error_class,
    120,
  );

let errorCode =
  'wf04_approval_failure_finalization_failed';

if (terminalFailure) {
  if (
    originalErrorClass ===
    'approval_response_timeout'
  ) {
    errorCode =
      'wf04_approval_response_timeout';

  } else if (
    originalErrorClass ===
    'gmail_send_failure'
  ) {
    errorCode =
      'wf04_gmail_send_failure';

  } else {
    errorCode =
      'wf04_invalid_approval_wait_result';
  }
}

return {
  json: {
    source_variant:
      'explicit_internal',

    source_workflow_name:
      'WF04 - Manual Approval',

    source_workflow_id:
      'I6nqXCOFa3qycHtY',

    source_execution_id:
      safeText(
        $execution.id,
        200,
      ),

    case_id:
      optionalUuid(
        input.case_id,
      ),

    correlation_id:
      optionalUuid(
        input.correlation_id,
      ),

    step_id:
      optionalUuid(
        input.approval_step_id,
      ),

    submission_id:
      optionalUuid(
        input.accepted_submission_id,
      ),

    external_operation_id:
      optionalUuid(
        input.operation_id,
      ),

    error_class:
      terminalFailure
        ? (
            originalErrorClass ??
            'approval_failure'
          )
        : 'workflow_contract_failure',

    error_code:
      errorCode,

    error_message:
      terminalFailure
        ? (
            safeText(
              input.error_message,
              1000,
            ) ??
            'WF04 manual approval failed terminally.'
          )
        : 'WF04 could not finalize the manual approval failure.',

    retryable:
      false,

    severity:
      terminalFailure
        ? 'error'
        : 'critical',

    requires_intervention:
      true,

    error_details: {
      next_action:
        input.next_action ?? null,

      approval_wait_outcome:
        input.approval_wait_outcome ?? null,

      failure_finalization_outcome:
        input.failure_finalization_outcome ?? null,

      operation_status:
        input.final_operation_status ?? null,

      approval_step_status:
        input.final_step_status ?? null,

      case_state:
        input.final_case_state ?? null,

      operation_attempt_count:
        input.operation_attempt_count ?? null,

      operation_max_attempts:
        input.operation_max_attempts ?? null,

      next_retry_at:
        input.next_retry_at ?? null,
    },
  },
};
